"""Demo: certified Goldbach decompositions."""
from __future__ import annotations
from typing import List, Optional, Tuple


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def find_goldbach_pair(n: int) -> Optional[Tuple[int, int]]:
    """Fuel-bounded scan for primes (p, q) with p + q = n."""
    for k in range(2, n + 1):
        if is_prime(k) and is_prime(n - k):
            return (k, n - k)
    return None


def verify_certificate(n: int, p: int, q: int) -> bool:
    return is_prime(p) and is_prime(q) and p + q == n


def goldbach_up_to(bound: int) -> Tuple[bool, Optional[int]]:
    for n in range(4, bound + 1, 2):
        if find_goldbach_pair(n) is None:
            return (False, n)
    return (True, None)


if __name__ == "__main__":
    for n in (4, 10, 28, 100, 1000):
        p, q = find_goldbach_pair(n)  # type: ignore[misc]
        assert verify_certificate(n, p, q)
        print(f"{n} = {p} + {q}")
    print("GoldbachUpTo(10000):", goldbach_up_to(10000))

"""Demo: Paley I construction of Hadamard matrices from primes q = 3 (mod 4)."""
from __future__ import annotations
from typing import List

Matrix = List[List[int]]


def quadratic_character(a: int, q: int) -> int:
    a %= q
    if a == 0:
        return 0
    residues = {(x * x) % q for x in range(1, q)}
    return 1 if a in residues else -1


def skew_conference_matrix(q: int) -> Matrix:
    """Order n = q + 1 skew conference matrix (q prime, q = 3 mod 4)."""
    n = q + 1
    C: Matrix = [[0] * n for _ in range(n)]
    for j in range(1, n):
        C[0][j] = 1
        C[j][0] = -1
    for a in range(q):
        for b in range(q):
            C[a + 1][b + 1] = quadratic_character(a - b, q)
    return C


def matmul(A: Matrix, B: Matrix) -> Matrix:
    n = len(A)
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)]
            for i in range(n)]


def transpose(M: Matrix) -> Matrix:
    n = len(M)
    return [[M[j][i] for j in range(n)] for i in range(n)]


def is_hadamard(H: Matrix) -> bool:
    n = len(H)
    if any(H[i][j] not in (1, -1) for i in range(n) for j in range(n)):
        return False
    P = matmul(H, transpose(H))
    return all(P[i][j] == (n if i == j else 0)
               for i in range(n) for j in range(n))


if __name__ == "__main__":
    for q in (3, 7, 11, 19, 23):
        n = q + 1
        C = skew_conference_matrix(q)
        H = [[(1 if i == j else 0) + C[i][j] for j in range(n)]
             for i in range(n)]
        assert is_hadamard(H)
        print(f"q={q} -> Hadamard order {n}: verified")

