function chi(a, q):
    a = a mod q
    if a == 0: return 0
    R = { (x*x) mod q : x in 1..q-1 }
    return 1 if a in R else -1

function skewConference(q):          # requires q prime, q = 3 (mod 4)
    n = q + 1
    C = zero matrix of size n x n
    for j in 1..n-1: C[0][j] = 1; C[j][0] = -1
    for a in 0..q-1:
        for b in 0..q-1:
            C[a+1][b+1] = chi(a - b, q)
    return C

function paleyHadamard(q):
    C = skewConference(q)
    return I(n) + C                  # n = q + 1

